-- A bottle is drawn from its Kind (ADR-0012). Generated by `drizzle-kit generate` from
-- `db/schema.ts`; the rows and the comments at the end are by hand.
--
-- The web view draws every Bottle and every Label as a silhouette: its **shape** — a Bordeaux,
-- a Burgundy, a flute, a spirit bottle, a sake bottle, a beer — and the **liquid** in it — red,
-- white, rosé, orange, amber, clear. Both are the Kind's, as columns on the row for the reason
-- `has_vintages` and `first_source` are (ADR-0002): a Kind a copy's owner adds is drawn by its
-- own row, never by a list of Kind names in code. A Label may override the shape — a Riesling
-- in a flute — and not the liquid, which is what the Kind *is*.
--
-- And a Kind can be hidden. A Kind with Labels is never deleted (the foreign key refuses it),
-- so retiring one the owner never uses is hiding it from every list a form or an assistant
-- picks from (spec §4, `/settings`).
--
-- The rows are written out per Kind id, as in `0010`, so every copy agrees on how its bottles
-- look until its owner changes them.

ALTER TABLE "kinds" ADD COLUMN "bottle_shape" text DEFAULT 'bordeaux' NOT NULL;--> statement-breakpoint
ALTER TABLE "kinds" ADD COLUMN "liquid" text DEFAULT 'clear' NOT NULL;--> statement-breakpoint
ALTER TABLE "kinds" ADD COLUMN "hidden" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "labels" ADD COLUMN "bottle_shape" text;--> statement-breakpoint
ALTER TABLE "kinds" ADD CONSTRAINT "kinds_bottle_shape_is_known" CHECK ("kinds"."bottle_shape" in ('bordeaux', 'burgundy', 'flute', 'spirit', 'sake', 'beer'));--> statement-breakpoint
ALTER TABLE "kinds" ADD CONSTRAINT "kinds_liquid_is_known" CHECK ("kinds"."liquid" in ('red', 'white', 'rose', 'orange', 'amber', 'clear'));--> statement-breakpoint
ALTER TABLE "labels" ADD CONSTRAINT "labels_bottle_shape_is_known" CHECK ("labels"."bottle_shape" is null or "labels"."bottle_shape" in ('bordeaux', 'burgundy', 'flute', 'spirit', 'sake', 'beer'));
--> statement-breakpoint
update kinds set
  bottle_shape = case id
    when 'kind_red'            then 'bordeaux'
    when 'kind_white'          then 'burgundy'
    when 'kind_rose'           then 'bordeaux'
    when 'kind_orange'         then 'burgundy'
    when 'kind_sparkling'      then 'flute'
    when 'kind_sweet'          then 'burgundy'
    when 'kind_fortified'      then 'bordeaux'
    when 'kind_vermouth'       then 'bordeaux'
    when 'kind_whisky'         then 'spirit'
    when 'kind_rum'            then 'spirit'
    when 'kind_gin'            then 'spirit'
    when 'kind_vodka'          then 'spirit'
    when 'kind_tequila_mezcal' then 'spirit'
    when 'kind_grappa'         then 'spirit'
    when 'kind_brandy'         then 'spirit'
    when 'kind_liqueur_amaro'  then 'spirit'
    when 'kind_other_spirit'   then 'spirit'
    when 'kind_sake'           then 'sake'
    when 'kind_beer'           then 'beer'
    when 'kind_cider'          then 'beer'
    when 'kind_mead'           then 'burgundy'
    else bottle_shape
  end,
  liquid = case id
    when 'kind_red'            then 'red'
    when 'kind_white'          then 'white'
    when 'kind_rose'           then 'rose'
    when 'kind_orange'         then 'orange'
    when 'kind_sparkling'      then 'white'
    when 'kind_sweet'          then 'white'
    when 'kind_fortified'      then 'amber'
    when 'kind_vermouth'       then 'amber'
    when 'kind_whisky'         then 'amber'
    when 'kind_rum'            then 'amber'
    when 'kind_gin'            then 'clear'
    when 'kind_vodka'          then 'clear'
    when 'kind_tequila_mezcal' then 'clear'
    when 'kind_grappa'         then 'clear'
    when 'kind_brandy'         then 'amber'
    when 'kind_liqueur_amaro'  then 'amber'
    when 'kind_other_spirit'   then 'amber'
    when 'kind_sake'           then 'clear'
    when 'kind_beer'           then 'amber'
    when 'kind_cider'          then 'white'
    when 'kind_mead'           then 'white'
    else liquid
  end;
--> statement-breakpoint
comment on column kinds.bottle_shape is
  'The silhouette a Label of this Kind is drawn as: bordeaux, burgundy, flute, spirit, sake or beer (ADR-0012). A Label may override it.';
--> statement-breakpoint
comment on column kinds.liquid is
  'The colour of what is in a bottle of this Kind, as drawn: red, white, rose, orange, amber or clear (ADR-0012).';
--> statement-breakpoint
comment on column kinds.hidden is
  'Left out of every list a form or an assistant picks a Kind from. A Kind with Labels is hidden, never deleted.';
--> statement-breakpoint
comment on column labels.bottle_shape is
  'This Label''s silhouette when it is not its Kind''s; null for the Kind''s (ADR-0012).';
